"""
CC91 论坛系统压力测试脚本

基于 Python 标准库实现，无需安装第三方依赖。
测试场景：
  1. 只读基准测试（公开接口）
  2. 认证+读写混合测试
  3. 并发写入测试（发帖/评论）
  4. 单接口极限吞吐测试

用法：
  python stress_test.py [--base-url http://localhost:8080] [--concurrency 50] [--duration 30]
"""

import argparse
import concurrent.futures
import json
import statistics
import sys
import threading
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass, field
from typing import Optional


# ──────────────────────────────────────────
# 数据结构
# ──────────────────────────────────────────

@dataclass
class RequestResult:
    success: bool
    status_code: int
    latency_ms: float
    error: Optional[str] = None
    body: Optional[str] = None


@dataclass
class ScenarioResult:
    name: str
    total_requests: int = 0
    success_count: int = 0
    fail_count: int = 0
    latencies: list = field(default_factory=list)
    status_codes: dict = field(default_factory=dict)
    errors: list = field(default_factory=list)
    duration_s: float = 0.0

    @property
    def rps(self):
        return self.total_requests / self.duration_s if self.duration_s > 0 else 0

    @property
    def avg_latency_ms(self):
        return statistics.mean(self.latencies) if self.latencies else 0

    @property
    def p50_latency_ms(self):
        return self._percentile(50)

    @property
    def p90_latency_ms(self):
        return self._percentile(90)

    @property
    def p95_latency_ms(self):
        return self._percentile(95)

    @property
    def p99_latency_ms(self):
        return self._percentile(99)

    @property
    def max_latency_ms(self):
        return max(self.latencies) if self.latencies else 0

    @property
    def min_latency_ms(self):
        return min(self.latencies) if self.latencies else 0

    def _percentile(self, p):
        if not self.latencies:
            return 0
        sorted_lat = sorted(self.latencies)
        idx = int(len(sorted_lat) * p / 100)
        return sorted_lat[min(idx, len(sorted_lat) - 1)]


# ──────────────────────────────────────────
# HTTP 客户端
# ──────────────────────────────────────────

class ApiClient:
    def __init__(self, base_url):
        self.base_url = base_url.rstrip("/")

