      uid,
      cid,
      FLOOR(RAND() * 5000),
      FLOOR(RAND() * 200),
      'PUBLISHED',
      DATE_SUB(NOW(), INTERVAL rand_days DAY),
      DATE_SUB(NOW(), INTERVAL rand_days DAY)
    );
    SET i = i + 1;
  END WHILE;
END //
